import org.jetbrains.java.decompiler.util.*;
import org.jetbrains.java.decompiler.util.collections.VBStyleCollection;
import org.jetbrains.java.decompiler.util.token.TextRange;

import java.io.IOException;
import java.util.*;
import java.util.stream.Collectors;

public class ClassWriter implements StatementWriter {
  private static final Key<ReferenceAwareRetention> REFERENCE_AWARE_RETENTION = Key.of("REFERENCE_AWARE_RETENTION");

  private static final Set<String> ERROR_DUMP_STOP_POINTS = new HashSet<>(Arrays.asList(
    "Fernflower.decompileContext",
    "MethodProcessor.codeToJava",
    "ClassWriter.writeMethod",
    "ClassWriter.methodLambdaToJava",
    "ClassWriter.classLambdaToJava"
  ));
  private final PoolInterceptor interceptor;
  private final IFabricJavadocProvider javadocProvider;

  private enum RetainedMemberType {
    CLASS, FIELD, METHOD
  }

  private static final class RetainedMember {
    private final String key;
    private final RetainedMemberType type;
    private final ClassNode node;
    private final ClassNode parent;
    private final StructField field;
    private final StructMethod method;

    private RetainedMember(String key, RetainedMemberType type, ClassNode node, ClassNode parent,
                           StructField field, StructMethod method) {
      this.key = key;
      this.type = type;
      this.node = node;
      this.parent = parent;
      this.field = field;
      this.method = method;
    }

    private static RetainedMember classMember(ClassNode node, ClassNode parent) {
      return new RetainedMember(classKey(node.classStruct.qualifiedName), RetainedMemberType.CLASS, node, parent, null, null);
    }

    private static RetainedMember field(ClassNode node, StructField field) {
      return new RetainedMember(fieldKey(node.classStruct.qualifiedName, field.getName(), field.getDescriptor()),
        RetainedMemberType.FIELD, node, null, field, null);
    }

    private static RetainedMember method(ClassNode node, StructMethod method) {
      return new RetainedMember(methodKey(node.classStruct.qualifiedName, method.getName(), method.getDescriptor()),
        RetainedMemberType.METHOD, node, null, null, method);
    }

    private static String classKey(String className) {
      return "C\u0000" + className;
    }

    private static String fieldKey(String className, String name, String descriptor) {
      return "F\u0000" + className + "\u0000" + name + "\u0000" + descriptor;
    }

    private static String methodKey(String className, String name, String descriptor) {
      return "M\u0000" + className + "\u0000" + name + "\u0000" + descriptor;
    }
  }

  private static final class ReferenceAwareRetention {
    private final Map<String, RetainedMember> candidates = new HashMap<>();
    private final Set<String> retained = new HashSet<>();
    private final Map<ClassNode, Boolean> processed = new IdentityHashMap<>();
    private final Map<ClassNode, String> processingErrors = new IdentityHashMap<>();

    private ReferenceAwareRetention(ClassNode root) {
      collectCandidates(root, null);
    }

    private void collectCandidates(ClassNode node, ClassNode parent) {
      for (StructField field : node.classStruct.getFields()) {
        if (field.isSynthetic()) {
          RetainedMember candidate = RetainedMember.field(node, field);
          candidates.putIfAbsent(candidate.key, candidate);
        }
      }

      for (StructMethod method : node.classStruct.getMethods()) {
        if (method.isSynthetic() || method.hasModifier(CodeConstants.ACC_BRIDGE)) {
          RetainedMember candidate = RetainedMember.method(node, method);
          candidates.putIfAbsent(candidate.key, candidate);
        }
      }

      for (ClassNode child : node.nested) {
        if (child.type == ClassNode.Type.MEMBER &&
            ((child.access & CodeConstants.ACC_SYNTHETIC) != 0 || child.classStruct.isSynthetic())) {
          RetainedMember candidate = RetainedMember.classMember(child, node);
          candidates.putIfAbsent(candidate.key, candidate);
        }
        collectCandidates(child, node);
      }
    }

    private boolean retainReferences(ClassWriter writer, TextBuffer buffer) {
      Set<String> references = new LinkedHashSet<>();
      buffer.visitTokens(new TextTokenVisitor(null) {
        private boolean[] code;

        @Override
        public void start(String content) {
          code = codePositions(content);
        }

        private boolean isCode(TextRange range) {
          return range.start >= 0 && range.start < code.length && code[range.start];
        }

        private void addReference(TextRange range, boolean declaration, String key) {
          if (!declaration && isCode(range)) {
            RetainedMember candidate = candidates.get(key);
            if (candidate != null && writer.wouldHide(candidate)) {
              references.add(key);
            }
          }
        }

        @Override
        public void visitClass(TextRange range, boolean declaration, String name) {
          addReference(range, declaration, RetainedMember.classKey(name));
        }

        @Override
        public void visitField(TextRange range, boolean declaration, String className, String name, FieldDescriptor descriptor) {
          addReference(range, declaration, RetainedMember.fieldKey(className, name, descriptor.descriptorString));
        }

        @Override
        public void visitMethod(TextRange range, boolean declaration, String className, String name, MethodDescriptor descriptor) {
          addReference(range, declaration, RetainedMember.methodKey(className, name, descriptor.toString()));
        }
      });

      boolean added = false;
      for (String reference : references) {
        added |= retained.add(reference);
      }
      return added;
    }

    private static boolean[] codePositions(String content) {
      boolean[] code = new boolean[content.length()];
      Arrays.fill(code, true);

      for (int i = 0; i < content.length(); i++) {
        char current = content.charAt(i);
        if (current == '/' && i + 1 < content.length()) {
          char next = content.charAt(i + 1);
          if (next == '/') {
            int end = content.indexOf('\n', i + 2);
            if (end < 0) end = content.length();
            Arrays.fill(code, i, end, false);
            i = end - 1;
          }
          else if (next == '*') {
            int end = content.indexOf("*/", i + 2);
            end = end < 0 ? content.length() : end + 2;
            Arrays.fill(code, i, end, false);
            i = end - 1;
          }
        }
        else if (current == '"' || current == '\'') {
          int end;
          if (current == '"' && i + 2 < content.length() && content.charAt(i + 1) == '"' && content.charAt(i + 2) == '"') {
            end = textBlockEnd(content, i + 3);
          }
          else {
            end = quotedEnd(content, i + 1, current);
          }
          Arrays.fill(code, i, end, false);
          i = end - 1;
        }
      }

      return code;
    }

    private static int quotedEnd(String content, int start, char quote) {
      boolean escaped = false;
      for (int i = start; i < content.length(); i++) {
        char current = content.charAt(i);
        if (escaped) {
          escaped = false;
        }
        else if (current == '\\') {
