    private boolean retainReferences(ClassWriter writer, TextBuffer buffer) {
      Set<String> references = new LinkedHashSet<>();
      buffer.visitTokens(new TextTokenVisitor(null) {
        private boolean[] code;

        @Override
        public void start(String content) {
          code = codePositions(content);
        }

        private boolean isCode(TextRange range) {
          return range.start >= 0 && range.start < code.length && code[range.start];
        }

        private void addReference(TextRange range, boolean declaration, String key) {
          if (!declaration && isCode(range)) {
            RetainedMember candidate = candidates.get(key);
            if (candidate != null && writer.wouldHide(candidate)) {
              references.add(key);
            }
          }
        }

        @Override
        public void visitClass(TextRange range, boolean declaration, String name) {
          addReference(range, declaration, RetainedMember.classKey(name));
        }

        @Override
        public void visitField(TextRange range, boolean declaration, String className, String name, FieldDescriptor descriptor) {
          addReference(range, declaration, RetainedMember.fieldKey(className, name, descriptor.descriptorString));
        }

        @Override
        public void visitMethod(TextRange range, boolean declaration, String className, String name, MethodDescriptor descriptor) {
          addReference(range, declaration, RetainedMember.methodKey(className, name, descriptor.toString()));
        }
      });

      boolean added = false;
      for (String reference : references) {
        added |= retained.add(reference);
      }
      return added;
    }

    private static boolean[] codePositions(String content) {
      boolean[] code = new boolean[content.length()];
      Arrays.fill(code, true);

      for (int i = 0; i < content.length(); i++) {
        char current = content.charAt(i);
        if (current == '/' && i + 1 < content.length()) {
          char next = content.charAt(i + 1);
          if (next == '/') {
            int end = content.indexOf('\n', i + 2);
            if (end < 0) end = content.length();
            Arrays.fill(code, i, end, false);
            i = end - 1;
          }
          else if (next == '*') {
            int end = content.indexOf("*/", i + 2);
            end = end < 0 ? content.length() : end + 2;
            Arrays.fill(code, i, end, false);
            i = end - 1;
          }
        }
        else if (current == '"' || current == '\'') {
