    if (next != null) {
      next.visitLocal(range, declaration, className, methodName, methodDescriptor, index, name);
    }
  }

  public void end() {
    if (next != null) {
      next.end();
    }
  }

  public interface Factory {
    TextTokenVisitor create(TextTokenVisitor next);

    default Factory andThen(Factory after) {
