   128	    private void collectCandidates(ClassNode node, ClassNode parent) {
   129	      for (StructField field : node.classStruct.getFields()) {
   130	        if (field.isSynthetic()) {
   131	          RetainedMember candidate = RetainedMember.field(node, field);
   132	          candidates.putIfAbsent(candidate.key, candidate);
   133	        }
   134	      }
   135	
   136	      for (StructMethod method : node.classStruct.getMethods()) {
   137	        if (method.isSynthetic() || method.hasModifier(CodeConstants.ACC_BRIDGE)) {
   138	          RetainedMember candidate = RetainedMember.method(node, method);
   139	          candidates.putIfAbsent(candidate.key, candidate);
   140	        }
   141	      }
   142	
   143	      for (ClassNode child : node.nested) {
   144	        if (child.type == ClassNode.Type.MEMBER &&
   145	            ((child.access & CodeConstants.ACC_SYNTHETIC) != 0 || child.classStruct.isSynthetic())) {
   146	          RetainedMember candidate = RetainedMember.classMember(child, node);
   147	          candidates.putIfAbsent(candidate.key, candidate);
   148	        }
   149	        collectCandidates(child, node);
   150	      }
   151	    }
