   153	    private boolean retainReferences(ClassWriter writer, TextBuffer buffer) {
   154	      Set<String> references = new LinkedHashSet<>();
   155	      buffer.visitTokens(new TextTokenVisitor(null) {
   156	        private boolean[] code;
   157	
   158	        @Override
   159	        public void start(String content) {
   160	          code = codePositions(content);
   161	        }
   162	
   163	        private boolean isCode(TextRange range) {
   164	          return range.start >= 0 && range.start < code.length && code[range.start];
   165	        }
   166	
   167	        private void addReference(TextRange range, boolean declaration, String key) {
   168	          if (!declaration && isCode(range)) {
   169	            RetainedMember candidate = candidates.get(key);
   170	            if (candidate != null && writer.wouldHide(candidate)) {
   171	              references.add(key);
   172	            }
   173	          }
   174	        }
   175	
   176	        @Override
   177	        public void visitClass(TextRange range, boolean declaration, String name) {
   178	          addReference(range, declaration, RetainedMember.classKey(name));
   179	        }
   180	
   181	        @Override
   182	        public void visitField(TextRange range, boolean declaration, String className, String name, FieldDescriptor descriptor) {
   183	          addReference(range, declaration, RetainedMember.fieldKey(className, name, descriptor.descriptorString));
   184	        }
   185	
   186	        @Override
   187	        public void visitMethod(TextRange range, boolean declaration, String className, String name, MethodDescriptor descriptor) {
   188	          addReference(range, declaration, RetainedMember.methodKey(className, name, descriptor.toString()));
   189	        }
   190	      });
   191	
   192	      boolean added = false;
   193	      for (String reference : references) {
   194	        added |= retained.add(reference);
   195	      }
   196	      return added;
   197	    }
