   199	    private static boolean[] codePositions(String content) {
   200	      boolean[] code = new boolean[content.length()];
   201	      Arrays.fill(code, true);
   202	
   203	      for (int i = 0; i < content.length(); i++) {
   204	        char current = content.charAt(i);
   205	        if (current == '/' && i + 1 < content.length()) {
   206	          char next = content.charAt(i + 1);
   207	          if (next == '/') {
   208	            int end = content.indexOf('\n', i + 2);
   209	            if (end < 0) end = content.length();
   210	            Arrays.fill(code, i, end, false);
   211	            i = end - 1;
   212	          }
   213	          else if (next == '*') {
   214	            int end = content.indexOf("*/", i + 2);
   215	            end = end < 0 ? content.length() : end + 2;
   216	            Arrays.fill(code, i, end, false);
   217	            i = end - 1;
   218	          }
   219	        }
   220	        else if (current == '"' || current == '\'') {
   221	          int end;
   222	          if (current == '"' && i + 2 < content.length() && content.charAt(i + 1) == '"' && content.charAt(i + 2) == '"') {
   223	            end = textBlockEnd(content, i + 3);
   224	          }
   225	          else {
   226	            end = quotedEnd(content, i + 1, current);
   227	          }
   228	          Arrays.fill(code, i, end, false);
   229	          i = end - 1;
   230	        }
   231	      }
   232	
   233	      return code;
   234	    }
   235	
   236	    private static int quotedEnd(String content, int start, char quote) {
   237	      boolean escaped = false;
   238	      for (int i = start; i < content.length(); i++) {
   239	        char current = content.charAt(i);
   240	        if (escaped) {
   241	          escaped = false;
   242	        }
   243	        else if (current == '\\') {
   244	          escaped = true;
   245	        }
   246	        else if (current == quote) {
   247	          return i + 1;
   248	        }
   249	      }
   250	      return content.length();
   251	    }
   252	
   253	    private static int textBlockEnd(String content, int start) {
   254	      for (int i = start; i + 2 < content.length(); i++) {
   255	        if (content.charAt(i) == '"' && content.charAt(i + 1) == '"' && content.charAt(i + 2) == '"' &&
   256	            (i == 0 || content.charAt(i - 1) != '\\')) {
   257	          return i + 3;
   258	        }
   259	      }
   260	      return content.length();
   261	    }
   262	  }
