  private static final class ReferenceAwareRetention {
    private final ClassNode root;
    private final Map<String, RetainedMember> candidates = new LinkedHashMap<>();
    private final Set<String> retained = new HashSet<>();
    private final Map<ClassNode, Boolean> processed = new IdentityHashMap<>();
    private final Map<ClassNode, String> processingErrors = new IdentityHashMap<>();

    private ReferenceAwareRetention(ClassNode root) {
      this.root = root;
      collectCandidates(root, null, Collections.newSetFromMap(new IdentityHashMap<>()));
    }

    private void collectCandidates(ClassNode node, ClassNode parent, Set<ClassNode> visited) {
      if (!visited.add(node)) {
        return;
      }

      for (StructField field : node.classStruct.getFields()) {
        if (field.isSynthetic()) {
          RetainedMember candidate = RetainedMember.field(node, field);
          candidates.putIfAbsent(candidate.key, candidate);
        }
      }

      for (StructMethod method : node.classStruct.getMethods()) {
        if (method.isSynthetic() || method.hasModifier(CodeConstants.ACC_BRIDGE)) {
          RetainedMember candidate = RetainedMember.method(node, method);
          candidates.putIfAbsent(candidate.key, candidate);
        }
      }

      for (ClassNode child : node.nested) {
        if (child.type == ClassNode.Type.MEMBER &&
            ((child.access & CodeConstants.ACC_SYNTHETIC) != 0 || child.classStruct.isSynthetic())) {
          RetainedMember candidate = RetainedMember.classMember(child, node);
          candidates.putIfAbsent(candidate.key, candidate);
        }
        collectCandidates(child, node, visited);
      }
    }

    private boolean retainReferences(TextBuffer buffer) {
      Set<String> declarations = new HashSet<>();
      Set<String> references = new LinkedHashSet<>();
      buffer.visitTokens(new TextTokenVisitor(null) {
        private boolean[] code;

        @Override
        public void start(String content) {
          code = codePositions(content);
        }

        private boolean isCode(TextRange range) {
          return range.start >= 0 && range.start < code.length && code[range.start];
        }

        private void addReference(TextRange range, boolean declaration, String key) {
          if (candidates.containsKey(key) && isCode(range)) {
            if (declaration) {
              declarations.add(key);
            }
            else {
              references.add(key);
            }
          }
        }

        @Override
        public void visitClass(TextRange range, boolean declaration, String name) {
          addReference(range, declaration, RetainedMember.classKey(name));
        }

        @Override
        public void visitField(TextRange range, boolean declaration, String className, String name, FieldDescriptor descriptor) {
          addReference(range, declaration, RetainedMember.fieldKey(className, name, descriptor.descriptorString));
        }

        @Override
        public void visitMethod(TextRange range, boolean declaration, String className, String name, MethodDescriptor descriptor) {
          addReference(range, declaration, RetainedMember.methodKey(className, name, descriptor.toString()));
        }
      });

      boolean added = false;
      for (String reference : references) {
        if (!declarations.contains(reference)) {
          added |= retain(reference);
        }
      }
      return added;
    }

    private boolean retain(String key) {
      RetainedMember candidate = candidates.get(key);
      if (candidate == null) {
        return false;
      }

      if (!retained.add(key)) {
        return false;
      }

      boolean added = true;
      if (candidate.type == RetainedMemberType.CLASS && candidate.parent != null) {
        RetainedMember parent = candidates.get(RetainedMember.classKey(candidate.parent.classStruct.qualifiedName));
        if (parent != null) {
          added |= retain(parent.key);
        }
      }
      return added;
    }

    private static boolean[] codePositions(String content) {
      boolean[] code = new boolean[content.length()];
      Arrays.fill(code, true);

      for (int i = 0; i < content.length(); i++) {
        char current = content.charAt(i);
        if (current == '/' && i + 1 < content.length()) {
          char next = content.charAt(i + 1);
          if (next == '/') {
            int end = content.indexOf('\n', i + 2);
            if (end < 0) end = content.length();
            Arrays.fill(code, i, end, false);
            i = end - 1;
          }
          else if (next == '*') {
            int end = content.indexOf("*/", i + 2);
            end = end < 0 ? content.length() : end + 2;
            Arrays.fill(code, i, end, false);
          if (hide) continue;

          if (hasContent.get()) {
            buffer.appendLineSeparator();
          }
          TextBuffer clsBuffer = new TextBuffer();
          writeClass(inner, clsBuffer, indent + 1);
          haveContent.run();
          buffer.append(clsBuffer);
        }
      }

      if (hasContent.get() || node.type != ClassNode.Type.ANONYMOUS) {
        // Skip indent for anonymous classes with no content, since we also skipped the newline in the cls definition
        buffer.appendIndent(indent);
      }
      buffer.append('}');

      if (node.type != ClassNode.Type.ANONYMOUS) {
        buffer.appendLineSeparator();
      }
    }
    finally {
      DecompilerContext.setProperty(DecompilerContext.CURRENT_CLASS_NODE, outerNode);
    }

    DecompilerContext.getLogger().endWriteClass();
  }

