  private static void resetAnnotationWriteState(ClassNode node, Set<ClassNode> visited) {
    if (!visited.add(node)) {
      return;
    }

    resetAnnotationWriteState(node.classStruct);
    for (StructField field : node.classStruct.getFields()) {
      resetAnnotationWriteState(field);
    }
    List<StructRecordComponent> components = node.classStruct.getRecordComponents();
    if (components != null) {
      for (StructRecordComponent component : components) {
        resetAnnotationWriteState(component);
      }
    }
    for (StructMethod method : node.classStruct.getMethods()) {
      resetAnnotationWriteState(method);
    }
