    private static int textBlockEnd(String content, int start) {
      for (int i = start; i + 2 < content.length(); i++) {
        if (content.charAt(i) == '"' && content.charAt(i + 1) == '"' && content.charAt(i + 2) == '"' &&
            !isEscaped(content, i)) {
          return i + 3;
        }
      }
      return content.length();
    }

    private static boolean isEscaped(String content, int position) {
      int backslashes = 0;
      for (int i = position - 1; i >= 0 && content.charAt(i) == '\\'; i--) {
        backslashes++;
      }
      return (backslashes & 1) != 0;
    }
  }

